# Que el juez encuentre solo la prueba que cubre lo que se cambio, para no tener que
# decirsela: busca las vigias que nombran el archivo y las juzga una por una.
def juzgar_con_vecinas(raiz, ruta_relativa, texto_viejo, texto_nuevo):
    """Busca sola la prueba que cubre el archivo y la juzga.

    Devuelve un diccionario con ok, prueba y razon. Nunca lanza error: si algo
    revienta, ok en None, prueba en None y la razon lo explica.
    """
    try:
        from arnes import vecinas

        lista_vigias = vecinas.lista_de_vigias(raiz)
        encontradas = vecinas.vecinas_por_pieza([ruta_relativa], raiz, lista_vigias)

        if not encontradas:
            return {
                'ok': None,
                'prueba': None,
                'razon': (
                    'ninguna prueba nombra ese archivo, asi que no hay nada que '
                    'correr para comprobarlo'
                ),
            }

        for vigia in encontradas:
            ruta_vigia = str(raiz) + '/' + str(vigia)
            ruta_archivo = str(raiz) + '/' + str(ruta_relativa)
            resultado = juzgar(
                raiz, ruta_vigia, ruta_archivo, texto_viejo, texto_nuevo
            )

            if not resultado.get('antes_roja'):
                continue

            if resultado.get('despues_verde') and resultado.get('vuelve_roja'):
                return {
                    'ok': True,
                    'prueba': vigia,
                    'razon': resultado.get('razon', ''),
                }

            return {
                'ok': False,
                'prueba': vigia,
                'razon': resultado.get('razon', ''),
            }

        return {
            'ok': None,
            'prueba': None,
            'razon': (
                'ninguna de las pruebas que nombran ese archivo estaba roja, asi '
                'que no habia nada que demostrar'
            ),
        }
    except Exception as error:
        return {
            'ok': None,
            'prueba': None,
            'razon': 'al buscar la prueba que cubre el archivo, revento: %s' % error,
        }
